import random

def generate_code():
    return random.randint(100, 999)

def get_guess():
    while True:
        try:
            guess = int(input("Enter your guess (3-digit number): "))
            if 100 <= guess <= 999:
                return guess
            else:
                print("Please enter a valid 3-digit number.")
        except ValueError:
            print("Invalid input. Please enter a number.")

def check_guess(code, guess):
    if guess == code:
        return "Correct!"
    elif guess < code:
        return "Too Low"
    else:
        return "Too High"

def play_game():
    code = generate_code()
    attempts = 5
    print("Welcome to Mystery Box! You have 5 attempts to guess the 3-digit code.")
    for _ in range(attempts):
        guess = get_guess()
